// ──────────────────────────── tests ──────────────────────────────────────

test('push adds to the top and peek reads it without removing', () => {
  const s = new Stack();
  s.push('a');
  s.push('b');
  eq(s.peek(), 'b');
  eq(s.size(), 2);
});

test('pop returns values in last-in-first-out order', () => {
  const s = new Stack();
  for (const n of [1, 2, 3]) s.push(n);
  eq(s.pop(), 3);
  eq(s.pop(), 2);
  eq(s.pop(), 1);
});

test('pop and peek on an empty stack return undefined', () => {
  const s = new Stack();
  eq(s.pop(), undefined);
  eq(s.peek(), undefined);
});

test('isEmpty flips as items come and go', () => {
  const s = new Stack();
  eq(s.isEmpty(), true);
  s.push('x');
  eq(s.isEmpty(), false);
  s.pop();
  eq(s.isEmpty(), true);
});

test('size counts only what is still on the stack', () => {
  const s = new Stack();
  for (const n of [1, 2, 3, 4]) s.push(n);
  s.pop();
  eq(s.size(), 3);
});

test('application: the back button pops the most recent page', () => {
  const history = new Stack();
  for (const page of ['/home', '/docs', '/docs/api']) history.push(page);
  eq(history.pop(), '/docs/api');
  eq(history.peek(), '/docs');
  eq(history.size(), 2);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('accepts a simple matched pair', () => {
  eq(isBalanced('()'), true);
});

test('accepts correctly nested mixed brackets', () => {
  eq(isBalanced('{[()]}'), true);
});

test('rejects a closer that does not match the top of the stack', () => {
  eq(isBalanced('(]'), false);
});

test('rejects crossed brackets that overlap instead of nesting', () => {
  eq(isBalanced('([)]'), false);
});

test('rejects an opener that is never closed', () => {
  eq(isBalanced('(()'), false);
});

test('rejects a closer that arrives with nothing open', () => {
  eq(isBalanced(')('), false);
});

test('treats the empty string as balanced', () => {
  eq(isBalanced(''), true);
});

test('application: checks a code snippet and ignores non-bracket text', () => {
  const good = 'function f(a) { return [a, { id: 1 }]; }';
  const bad = 'function f(a) { return [a, { id: 1 }; }';
  eq(isBalanced(good), true);
  eq(isBalanced(bad), false);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('starts on the initial value with nothing to undo', () => {
  const h = new UndoHistory('start');
  eq(h.canUndo(), false);
  eq(h.value, 'start');
});

test('set replaces the current value and makes undo available', () => {
  const h = new UndoHistory(1);
  h.set(2);
  eq(h.value, 2);
  eq(h.canUndo(), true);
});

test('undo restores the previous value and returns it', () => {
  const h = new UndoHistory('a');
  h.set('b');
  eq(h.undo(), 'a');
  eq(h.value, 'a');
});

test('undo walks back one step at a time', () => {
  const h = new UndoHistory(0);
  h.set(1);
  h.set(2);
  h.set(3);
  eq(h.undo(), 2);
  eq(h.undo(), 1);
  eq(h.value, 1);
  eq(h.canUndo(), true);
});

test('undo with an empty past is a no-op returning undefined', () => {
  const h = new UndoHistory('only');
  eq(h.undo(), undefined);
  eq(h.value, 'only');
});

test('undoing everything lands back on the initial value', () => {
  const h = new UndoHistory('v0');
  h.set('v1');
  h.set('v2');
  h.undo();
  h.undo();
  eq(h.value, 'v0');
  eq(h.canUndo(), false);
});

test('application: an editor undoes two keystrokes', () => {
  const editor = new UndoHistory('');
  for (const text of ['h', 'he', 'hel', 'hell', 'hello']) editor.set(text);
  editor.undo();
  editor.undo();
  eq(editor.value, 'hel');
  editor.set('help');
  eq(editor.value, 'help');
  eq(editor.undo(), 'hel');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('dequeue returns values in first-in-first-out order', () => {
  const q = new Queue();
  for (const n of [1, 2, 3]) q.enqueue(n);
  eq(q.dequeue(), 1);
  eq(q.dequeue(), 2);
  eq(q.dequeue(), 3);
});

test('peek shows the front without removing it', () => {
  const q = new Queue();
  q.enqueue('a');
  q.enqueue('b');
  eq(q.peek(), 'a');
  eq(q.peek(), 'a');
  eq(q.size(), 2);
});

test('dequeue and peek on an empty queue return undefined', () => {
  const q = new Queue();
  eq(q.dequeue(), undefined);
  eq(q.peek(), undefined);
  eq(q.isEmpty(), true);
});

test('size counts only the items still waiting', () => {
  const q = new Queue();
  for (const n of [1, 2, 3, 4]) q.enqueue(n);
  q.dequeue();
  q.dequeue();
  eq(q.size(), 2);
  eq(q.isEmpty(), false);
});

test('dequeue advances head instead of shifting the array', () => {
  const q = new Queue();
  for (const n of [1, 2, 3]) q.enqueue(n);
  q.dequeue();
  q.dequeue();
  eq(q.head, 2);
  ok(q.items.length >= 3, 'nothing should be spliced out of items');
});

test('interleaved enqueue and dequeue keep the order', () => {
  const q = new Queue();
  q.enqueue('a');
  q.enqueue('b');
  eq(q.dequeue(), 'a');
  q.enqueue('c');
  eq(q.dequeue(), 'b');
  eq(q.dequeue(), 'c');
  eq(q.isEmpty(), true);
});

test('application: a print spooler serves jobs in arrival order', () => {
  const spooler = new Queue();
  spooler.enqueue('invoice.pdf');
  spooler.enqueue('poster.png');
  const printed = [];
  printed.push(spooler.dequeue());
  spooler.enqueue('contract.docx');
  while (!spooler.isEmpty()) printed.push(spooler.dequeue());
  eq(printed, ['invoice.pdf', 'poster.png', 'contract.docx']);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('dequeue returns values in first-in-first-out order', () => {
  const q = new StackQueue();
  for (const n of [1, 2, 3]) q.enqueue(n);
  eq(q.dequeue(), 1);
  eq(q.dequeue(), 2);
  eq(q.dequeue(), 3);
});

test('items enqueued after a dequeue still go to the back', () => {
  const q = new StackQueue();
  q.enqueue('a');
  q.enqueue('b');
  eq(q.dequeue(), 'a');
  q.enqueue('c');
  eq(q.dequeue(), 'b');
  eq(q.dequeue(), 'c');
});

test('peek shows the front without removing it', () => {
  const q = new StackQueue();
  q.enqueue('x');
  q.enqueue('y');
  eq(q.peek(), 'x');
  eq(q.peek(), 'x');
  eq(q.size(), 2);
});

test('dequeue and peek on an empty queue return undefined', () => {
  const q = new StackQueue();
  eq(q.dequeue(), undefined);
  eq(q.peek(), undefined);
  eq(q.size(), 0);
});

test('size counts both stacks together', () => {
  const q = new StackQueue();
  for (const n of [1, 2, 3]) q.enqueue(n);
  q.dequeue();
  q.enqueue(4);
  eq(q.size(), 3);
});

test('transfers only when the outbox is empty', () => {
  const q = new StackQueue();
  for (const n of [1, 2, 3]) q.enqueue(n);
  eq(q.dequeue(), 1);
  q.enqueue(4);
  eq(q.outbox, [3, 2], 'the reversed leftovers stay in the outbox');
  eq(q.inbox, [4], 'the newcomer waits in the inbox');
  eq(q.dequeue(), 2);
});

test('survives many rounds of mixed traffic', () => {
  const q = new StackQueue();
  const out = [];
  for (let n = 1; n <= 6; n += 1) {
    q.enqueue(n);
    if (n % 2 === 0) out.push(q.dequeue());
  }
  while (q.size() > 0) out.push(q.dequeue());
  eq(out, [1, 2, 3, 4, 5, 6]);
});

test('application: a chat relay forwards messages in order', () => {
  const relay = new StackQueue();
  relay.enqueue('hello');
  relay.enqueue('are you there?');
  const sent = [relay.dequeue()];
  relay.enqueue('never mind');
  while (relay.size() > 0) sent.push(relay.dequeue());
  eq(sent, ['hello', 'are you there?', 'never mind']);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('a task shorter than the quantum runs exactly once', () => {
  eq(roundRobin([{ name: 'a', work: 1 }], 3), ['a']);
});

test('a task longer than the quantum comes back around', () => {
  eq(roundRobin([{ name: 'a', work: 3 }], 2), ['a', 'a']);
});

test('finished tasks drop out of the rotation', () => {
  const tasks = [
    { name: 'a', work: 3 },
    { name: 'b', work: 1 },
  ];
  eq(roundRobin(tasks, 2), ['a', 'b', 'a']);
});

test('a quantum of 1 interleaves the tasks strictly', () => {
  const tasks = [
    { name: 'a', work: 2 },
    { name: 'b', work: 3 },
  ];
  eq(roundRobin(tasks, 1), ['a', 'b', 'a', 'b', 'b']);
});

test('an empty task list schedules nothing', () => {
  eq(roundRobin([], 4), []);
});

test('leaves the caller task objects untouched', () => {
  const tasks = [{ name: 'a', work: 5 }];
  roundRobin(tasks, 2);
  eq(tasks, [{ name: 'a', work: 5 }]);
});

test('application: three build steps share the CPU fairly', () => {
  const steps = [
    { name: 'lint', work: 1 },
    { name: 'test', work: 5 },
    { name: 'build', work: 2 },
  ];
  eq(roundRobin(steps, 2), ['lint', 'test', 'build', 'test', 'test']);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('keeps items in insertion order while there is room', () => {
  const buf = new CircularBuffer(3);
  buf.push('a');
  buf.push('b');
  eq(buf.toArray(), ['a', 'b']);
  eq(buf.size(), 2);
});

test('isFull flips exactly at capacity', () => {
  const buf = new CircularBuffer(2);
  buf.push(1);
  eq(buf.isFull(), false);
  buf.push(2);
  eq(buf.isFull(), true);
});

test('overwrites the oldest item once it is full', () => {
  const buf = new CircularBuffer(3);
  for (const ch of ['a', 'b', 'c', 'd']) buf.push(ch);
  eq(buf.toArray(), ['b', 'c', 'd']);
  eq(buf.size(), 3);
});

test('keeps wrapping cleanly past a full lap', () => {
  const buf = new CircularBuffer(3);
  for (let n = 1; n <= 7; n += 1) buf.push(n);
  eq(buf.toArray(), [5, 6, 7]);
});

test('a capacity of 1 keeps only the newest value', () => {
  const buf = new CircularBuffer(1);
  buf.push('old');
  buf.push('new');
  eq(buf.toArray(), ['new']);
  eq(buf.size(), 1);
});

test('an empty buffer reports empty', () => {
  const buf = new CircularBuffer(4);
  eq(buf.toArray(), []);
  eq(buf.size(), 0);
});

test('the backing array never grows past the capacity', () => {
  const buf = new CircularBuffer(3);
  for (let n = 0; n < 50; n += 1) buf.push(n);
  eq(buf.slots.length, 3);
  eq(buf.toArray(), [47, 48, 49]);
});

test('application: keeps the last 5 lines of a noisy log', () => {
  const tail = new CircularBuffer(5);
  for (let n = 1; n <= 12; n += 1) tail.push(`line-${n}`);
  eq(tail.toArray(), [
    'line-8',
    'line-9',
    'line-10',
    'line-11',
    'line-12',
  ]);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('makeNode holds a value and points nowhere yet', () => {
  eq(makeNode('a'), { value: 'a', next: null });
});

test('nodes can be chained together by hand', () => {
  const first = makeNode(1);
  const second = makeNode(2);
  first.next = second;
  eq(first.next.value, 2);
  eq(first.next.next, null);
});

test('push on an empty list sets both head and tail', () => {
  const list = new LinkedList();
  list.push('only');
  eq(list.head.value, 'only');
  eq(list.tail.value, 'only');
  eq(list.head.next, null);
});

test('push appends at the tail', () => {
  const list = new LinkedList();
  list.push('a');
  list.push('b');
  list.push('c');
  eq(list.head.value, 'a');
  eq(list.head.next.value, 'b');
  eq(list.tail.value, 'c');
  eq(list.tail.next, null);
});

test('toArray walks the chain from head to tail', () => {
  const list = new LinkedList();
  for (const n of [10, 20, 30]) list.push(n);
  eq(list.toArray(), [10, 20, 30]);
});

test('an empty list has no head and an empty array form', () => {
  const list = new LinkedList();
  eq(list.toArray(), []);
  ok(list.head === null);
  eq(list.length, 0);
});

test('length grows with every push', () => {
  const list = new LinkedList();
  for (const n of [1, 2, 3, 4]) list.push(n);
  eq(list.length, 4);
});

test('application: a playlist keeps songs in the order added', () => {
  const playlist = new LinkedList();
  for (const song of ['intro', 'verse', 'chorus']) playlist.push(song);
  eq(playlist.toArray(), ['intro', 'verse', 'chorus']);
  eq(playlist.tail.value, 'chorus');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('find returns the first value the predicate accepts', () => {
  const list = listOf(3, 8, 12, 20);
  eq(list.find((v) => v > 5), 8);
});

test('find returns undefined when nothing matches', () => {
  const list = listOf(1, 2, 3);
  eq(list.find((v) => v > 99), undefined);
});

test('insertAt(0) becomes the new head', () => {
  const list = listOf('a', 'b');
  eq(list.insertAt(0, 'z'), true);
  eq(list.toArray(), ['z', 'a', 'b']);
  eq(list.head.value, 'z');
  eq(list.length, 3);
});

test('insertAt in the middle relinks both sides', () => {
  const list = listOf('a', 'b', 'c');
  list.insertAt(1, 'q');
  eq(list.toArray(), ['a', 'q', 'b', 'c']);
  eq(list.tail.value, 'c');
});

test('insertAt at the end appends and moves the tail', () => {
  const list = listOf('a', 'b');
  list.insertAt(2, 'c');
  eq(list.toArray(), ['a', 'b', 'c']);
  eq(list.tail.value, 'c');
  eq(list.tail.next, null);
});

test('insertAt out of range is refused and changes nothing', () => {
  const list = listOf('a', 'b');
  eq(list.insertAt(9, 'x'), false);
  eq(list.insertAt(-1, 'x'), false);
  eq(list.toArray(), ['a', 'b']);
  eq(list.length, 2);
});

test('removeAt unlinks the node and fixes head, tail and length', () => {
  const list = listOf('a', 'b', 'c');
  eq(list.removeAt(1), 'b');
  eq(list.toArray(), ['a', 'c']);
  eq(list.removeAt(0), 'a');
  eq(list.head.value, 'c');
  eq(list.removeAt(0), 'c');
  ok(list.head === null && list.tail === null);
  eq(list.length, 0);
  eq(list.removeAt(0), undefined);
});

test('application: a task list takes a rush job and a cancellation', () => {
  const tasks = listOf('email', 'report', 'invoice');
  tasks.insertAt(0, 'hotfix');
  eq(tasks.toArray(), ['hotfix', 'email', 'report', 'invoice']);
  eq(tasks.removeAt(2), 'report');
  eq(tasks.find((t) => t.startsWith('inv')), 'invoice');
  eq(tasks.toArray(), ['hotfix', 'email', 'invoice']);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('reverses the values of a three-node list', () => {
  const list = listOf('a', 'b', 'c');
  list.reverse();
  eq(list.toArray(), ['c', 'b', 'a']);
});

test('head and tail swap ends, and the new tail terminates', () => {
  const list = listOf(1, 2, 3, 4);
  list.reverse();
  eq(list.head.value, 4);
  eq(list.tail.value, 1);
  eq(list.tail.next, null);
});

test('an empty list survives being reversed', () => {
  const list = new LinkedList();
  list.reverse();
  eq(list.toArray(), []);
  ok(list.head === null && list.tail === null);
});

test('a single node list is unchanged', () => {
  const list = listOf('only');
  list.reverse();
  eq(list.toArray(), ['only']);
  eq(list.head, list.tail);
});

test('reuses the same node objects instead of rebuilding', () => {
  const list = listOf('a', 'b', 'c');
  const first = list.head;
  const last = list.tail;
  list.reverse();
  ok(list.head === last, 'the old tail node itself is the new head');
  ok(list.tail === first, 'the old head node itself is the new tail');
  ok(list.head.next.next === first);
});

test('length is untouched and a second reverse restores the order', () => {
  const list = listOf(1, 2, 3);
  list.reverse();
  eq(list.length, 3);
  list.reverse();
  eq(list.toArray(), [1, 2, 3]);
});

test('reverse returns the list so calls can be chained', () => {
  const list = listOf('x', 'y');
  eq(list.reverse().toArray(), ['y', 'x']);
});

test('application: replay a route backwards to walk home', () => {
  const route = listOf('home', 'main st', 'oak ave', 'office');
  route.reverse();
  eq(route.toArray(), ['office', 'oak ave', 'main st', 'home']);
  eq(route.head.value, 'office');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('the same string always hashes to the same number', () => {
  eq(hashString('hello world'), hashString('hello world'));
  eq(hashString(''), hashString(''));
});

test('always returns a non-negative integer', () => {
  for (const key of ['', 'a', 'zzzzzzzzzz', 'a longer sentence here', '💡']) {
    const h = hashString(key);
    ok(Number.isInteger(h), `expected an integer for ${JSON.stringify(key)}`);
    ok(h >= 0, `expected a non-negative number for ${JSON.stringify(key)}`);
  }
});

test('different words get different hashes', () => {
  ok(hashString('cat') !== hashString('dog'));
  ok(hashString('user:1') !== hashString('user:2'));
});

test('order matters, so anagrams do not collide', () => {
  ok(hashString('ab') !== hashString('ba'));
  ok(hashString('cat') !== hashString('act'));
});

test('a one-character difference changes the hash', () => {
  ok(hashString('session') !== hashString('sessions'));
});

test('bucketIndex always lands inside the table', () => {
  for (let n = 0; n < 200; n += 1) {
    const i = bucketIndex(`key-${n}`, 8);
    ok(Number.isInteger(i) && i >= 0 && i < 8, `out of range: ${i}`);
  }
});

test('bucketIndex is stable for the same key and size', () => {
  eq(bucketIndex('session-token', 16), bucketIndex('session-token', 16));
});

test('application: 200 user ids spread across all 8 buckets', () => {
  const counts = new Array(8).fill(0);
  for (let n = 0; n < 200; n += 1) counts[bucketIndex(`user-${n}`, 8)] += 1;
  ok(counts.every((c) => c > 0), `some bucket got nothing: ${counts}`);
  ok(counts.every((c) => c < 100), `one bucket took half the keys: ${counts}`);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('set then get returns the stored value', () => {
  const m = new HashMap();
  m.set('sky', 'blue');
  m.set('grass', 'green');
  eq(m.get('sky'), 'blue');
  eq(m.get('grass'), 'green');
  eq(m.get('ocean'), undefined, 'a key that was never set');
});

test('setting the same key twice overwrites instead of duplicating', () => {
  const m = new HashMap();
  m.set('sky', 'blue');
  m.set('sky', 'grey');
  eq(m.get('sky'), 'grey');
  eq(m.buckets.flat().length, 1, 'there should still be one entry');
});

test('has reports membership without returning the value', () => {
  const m = new HashMap();
  m.set('a', undefined);
  eq(m.has('a'), true, 'a key set to undefined is still present');
  eq(m.has('b'), false);
});

test('delete reports whether it removed anything', () => {
  const m = new HashMap();
  m.set('a', 1);
  eq(m.delete('a'), true);
  eq(m.delete('a'), false);
  eq(m.get('a'), undefined);
});

test('delete removes only the target key', () => {
  const m = new HashMap();
  m.set('a', 1);
  m.set('b', 2);
  m.set('c', 3);
  m.delete('b');
  eq(m.get('a'), 1);
  eq(m.get('c'), 3);
  eq(m.buckets.flat().length, 2);
});

test('hashIndex always points at a real bucket', () => {
  const m = new HashMap(4);
  for (const key of ['', 'a', 'zebra', 'user:42', 'a much longer key']) {
    const i = m.hashIndex(key);
    ok(Number.isInteger(i) && i >= 0 && i < 4, `bad index ${i} for ${key}`);
  }
});

test('collisions: a single-bucket map keeps its keys apart', () => {
  const m = new HashMap(1);
  m.set('one', 1);
  m.set('two', 2);
  m.set('three', 3);
  eq(m.buckets[0].length, 3, 'all three keys share the only bucket');
  eq(m.get('two'), 2);
  eq(m.delete('two'), true);
  eq(m.get('one'), 1);
  eq(m.get('three'), 3);
  eq(m.get('two'), undefined);
});

test('application: counts word frequency in a sentence', () => {
  const counts = new HashMap(8);
  const words = 'the cat sat on the mat the end'.split(' ');
  for (const word of words) {
    counts.set(word, (counts.get(word) ?? 0) + 1);
  }
  eq(counts.get('the'), 3);
  eq(counts.get('cat'), 1);
  eq(counts.has('dog'), false);
  eq(counts.buckets.flat().length, 6, 'six distinct words');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('the first insert becomes the root', () => {
  const tree = new BST();
  tree.insert(8);
  eq(tree.root.value, 8);
  ok(tree.root.left === null && tree.root.right === null);
});

test('smaller values go left and bigger values go right', () => {
  const tree = new BST();
  for (const n of [8, 3, 10]) tree.insert(n);
  eq(tree.root.left.value, 3);
  eq(tree.root.right.value, 10);
});

test('inserts keep descending until they find an empty slot', () => {
  const tree = new BST();
  for (const n of [8, 3, 10, 1, 6]) tree.insert(n);
  eq(tree.root.left.left.value, 1);
  eq(tree.root.left.right.value, 6);
});

test('contains finds values at every depth', () => {
  const tree = new BST();
  for (const n of [8, 3, 10, 1, 6, 14]) tree.insert(n);
  eq(tree.contains(8), true);
  eq(tree.contains(6), true);
  eq(tree.contains(14), true);
});

test('contains is false for a value that was never inserted', () => {
  const tree = new BST();
  for (const n of [8, 3, 10]) tree.insert(n);
  eq(tree.contains(7), false);
  eq(tree.contains(100), false);
});

test('contains on an empty tree is false', () => {
  const tree = new BST();
  eq(tree.contains(1), false);
});

test('duplicate inserts are ignored', () => {
  const tree = new BST();
  tree.insert(5);
  tree.insert(5);
  ok(tree.root.left === null && tree.root.right === null);
});

test('application: a spell-check dictionary of words', () => {
