  constructor() {
    this.items = [];
  }

  push(value) {
    throw new Error('TODO');
  }

  pop() {
    throw new Error('TODO');
  }

  peek() {
    throw new Error('TODO');
  }

  size() {
    throw new Error('TODO');
  }

  isEmpty() {
    throw new Error('TODO');
  }
}

