  cache.set('/users/3', { name: 'grace' });
  eq(cache.get('/users/1'), { name: 'ada' }, 'a cache hit');
  cache.set('/users/4', { name: 'alan' });
  eq(cache.keys(), ['/users/3', '/users/1', '/users/4']);
  eq(cache.get('/users/2'), undefined, 'the coldest entry was evicted');
});

