  eq(node.next, null);
});

test('application: two sorted log streams merge into one timeline', () => {
  const web = chain(101, 205, 400);
  const worker = chain(150, 300);
  eq(toArray(mergeSorted(web, worker)), [101, 150, 205, 300, 400]);
});

