  const infix = ['2', '*', '(', '(', '1', '+', '2', ')', '/', '3', ')'];
  eq(toPostfix(infix), ['2', '1', '2', '+', '3', '/', '*']);
  eq(evalRPN(toPostfix(infix)), 2);
});

