    throw new Error('TODO');
  }

  size() {
    throw new Error('TODO');
  }
}

const heapProperty = (items) =>
  items.every((v, i) => i === 0 || items[(i - 1) >> 1] >= v);

// ──────────────────────────── tests ──────────────────────────────────────

test('an empty heap peeks and extracts undefined', () => {
  const h = new MaxHeap();
  eq(h.peek(), undefined);
  eq(h.extractMax(), undefined);
  eq(h.size(), 0);
