  const h = new MaxHeap();
  for (const n of [5, 3, 8, 1, 9, 2]) h.insert(n);
  const out = [];
  while (h.size() > 0) out.push(h.extractMax());
  eq(out, [9, 8, 5, 3, 2, 1]);
});

