  const bids = new MaxHeap();
  for (const amount of [120, 95, 140]) bids.insert(amount);
  eq(bids.extractMax(), 140);
  bids.insert(200);
  eq(bids.extractMax(), 200, 'a late higher bid jumps the queue');
  eq(bids.extractMax(), 120);
