  eq(mergeKSorted([[1, 4, 7], [2, 5, 8], [3, 6, 9]]), [1, 2, 3, 4, 5, 6, 7, 8, 9]);
});

test('nothing to merge gives an empty array', () => {
  eq(mergeKSorted([]), []);
  eq(mergeKSorted([[], []]), []);
});

test('empty arrays are skipped, not stumbled over', () => {
